import React from 'react';
import styled from 'styled-components';

const SkillsSection = styled.section`
  max-width: 700px;
  margin: 0 auto;
  padding: 3rem 1.5rem;
  color: #fff;
`;

const Heading = styled.h2`
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 2rem;
  color: #fff;
`;

const SkillsList = styled.ul`
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem 2.5rem;
  list-style: none;
  padding: 0;
  margin: 0;
`;

const Skill = styled.li`
  font-size: 1.15rem;
  color: #aaa;
  font-weight: 600;
  letter-spacing: 0.5px;
`;

const skills = [
  'HTML',
  'CSS',
  'JavaScript',
  'React',
  'Tailwind CSS',
  'TypeScript',
];

const Skills = () => (
  <SkillsSection id="skills">
    <Heading>Skills</Heading>
    <SkillsList>
      {skills.map(skill => (
        <Skill key={skill}>{skill}</Skill>
      ))}
    </SkillsList>
  </SkillsSection>
);

export default Skills;
